import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.watermark.Watermark;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Reads a single gzipped CSV file of task events and emits TaskEvent records.
 * Emits {@link Watermark#MAX_WATERMARK} on completion so event-time session
 * windows close deterministically on bounded input.
 */
public class TaskEventSource implements SourceFunction<TaskEvent> {

    private final String path;
    private volatile boolean running = true;

    public TaskEventSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(
                        new GZIPInputStream(new FileInputStream(path)),
                        StandardCharsets.UTF_8))) {
            String line;
            while (running && (line = reader.readLine()) != null) {
                if (line.isEmpty()) continue;
                TaskEvent e = TaskEvent.fromCsv(line);
                ctx.collectWithTimestamp(e, e.getEventTimeMillis());
            }
        }
        ctx.emitWatermark(Watermark.MAX_WATERMARK);
    }

    @Override
    public void cancel() {
        running = false;
    }
}
